document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,data=new FormData(form);switch(form.id){case'bankForm':{const mode=form.dataset.mode,name=String(data.get('name')).trim(),value=Number(data.get('value'));if(!name||!Number.isFinite(value)||value<=0){toast('Confira o nome e o valor.');return;}if(mode==='charge'){show('Cobrança criada',`<section class="section"><h2>${currency(value)}</h2><p>${escapeHTML(name)}</p><div style="padding:20px;background:#ededf2;border-radius:12px;color:#333;overflow-wrap:anywhere">BCG-DEMO-${Date.now()}</div><p class="muted">Cobrança local de demonstração, sem recebimento automático.</p><button class="btn" data-open="bank">Voltar à conta</button></section>`);return;}if(value>state.balance){toast('Saldo insuficiente na demonstração.');return;}sheet(`Confirmar ${currency(value)} para ${name}?`,'Confirmar',()=>{state.balance=Math.round((state.balance-value)*100)/100;state.transactions.push({name,value:-value,date:new Date().toLocaleString('pt-BR')});save();bank();toast('Movimentação local concluída.');});break;}case'messageForm':{const input=$('messageInput'),text=input.value.trim();if(text)addMessage(text);break;}case'contactForm':{const name=String(data.get('name')).trim(),number=String(data.get('number')).trim();if(!name||!number)return;if(state.contacts.some(c=>c.number===number)){toast('Este número já está nos contatos.');return;}const id=Date.now();state.contacts.push({id,name,number});state.messages[id]=[];save();chat();toast('Contato salvo.');break;}case'postForm':{const caption=String(data.get('caption')).trim();if(!caption)return;state.posts.push({id:Date.now(),name:'lipee',caption,image:String(data.get('image')||''),likes:0,liked:false,saved:false,comments:[],a:'#e5b78c',b:'#537dae'});save();social();toast('Publicação criada.');break;}case'commentForm':{const p=state.posts.find(p=>p.id===Number(form.dataset.id));const text=String(data.get('text')).trim();if(p&&text){p.comments.push(text);save();social();}break;}case'noteForm':{const id=Number(form.dataset.id),title=String(data.get('title')).trim(),text=String(data.get('text'));if(!title)return;const note=state.notes.find(n=>n.id===id);if(note)Object.assign(note,{title,text});else state.notes.push({id,title,text});save();notes();toast('Nota salva.');break;}case'taskForm':{const text=String(data.get('text')).trim();if(text){state.tasks.push({id:Date.now(),text,done:false});save();tasks();}break;}case'eventForm':{const title=String(data.get('title')).trim(),time=String(data.get('time'));if(title&&time){state.pages.push({id:Date.now(),title,time});save();calendar();}break;}case'rideForm':toast('Corrida de demonstração solicitada para '+String(data.get('destination'))+'.');show('Vai · corrida',`<section class="section"><h2>Buscando motorista</h2><p>Destino: ${escapeHTML(data.get('destination'))}</p><p class="muted">Simulação local. Nenhum pedido foi enviado ao servidor.</p><button class="btn gray" data-open="rides">Cancelar simulação</button></section>`);break;case'browserForm':search(String(data.get('q')));break;case'pinForm':{const code=String(data.get('pin'));if(!/^\d{6}$/.test(code)){toast('Use exatamente seis números.');return;}if(pinPurpose==='verify'||pinPurpose==='remove'){if(code!==state.pin){toast('Código atual incorreto.');return;}if(pinPurpose==='remove'){state.pin='';save();pinSettings();toast('Código desativado.');return;}pinPurpose='new';pinForm();}else if(pinPurpose==='new'){draftPin=code;pinPurpose='confirm';pinForm();}else if(code===draftPin){state.pin=code;save();pinSettings();toast('Código salvo.');}else{toast('Os códigos não coincidem.');pinPurpose='new';pinForm();}break;}}});
document.addEventListener('input',e=>{if(e.target.id==='brightness'){state.brightness=Number(e.target.value);applyTheme();save();}if(e.target.id==='chatSearch')$('contactList').innerHTML=contactRows(e.target.value);if(e.target.id==='appSearch')$('searchResults').innerHTML=searchRows(e.target.value);if(e.target.id==='musicProgress'){musicSeconds=Number(e.target.value);if(localAudio)localAudio.currentTime=musicSeconds;$('musicElapsed').textContent=duration(musicSeconds);}});
$('photoInput').addEventListener('change',()=>{const file=$('photoInput').files[0];if(!file)return;if(!file.type.startsWith('image/')){toast('Escolha uma imagem.');return;}const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{const c=document.createElement('canvas'),scale=Math.min(1,800/img.width,800/img.height);c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);photoCallback?.(c.toDataURL('image/jpeg',.8));};img.onerror=()=>toast('Não foi possível abrir a imagem.');img.src=reader.result;};reader.readAsDataURL(file);});
async function voiceRecord(){if(recording&&recording.state==='recording'){recording.stop();toast('Gravação encerrada.');return;}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('Gravação exige um navegador com microfone permitido. Abra por HTTPS ou localhost.');return;}try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});recordParts=[];recording=new MediaRecorder(stream);const recipient=chatId;recording.ondataavailable=e=>{if(e.data.size)recordParts.push(e.data);};recording.onstop=()=>{stream.getTracks().forEach(t=>t.stop());const blob=new Blob(recordParts,{type:recording.mimeType});const reader=new FileReader();reader.onload=()=>{chatId=recipient;addMessage('Mensagem de áudio',reader.result);};reader.readAsDataURL(blob);};recording.start();toast('Gravando. Toque no microfone para finalizar.');setTimeout(()=>{if(recording?.state==='recording')recording.stop();},30000);}catch(e){toast('Microfone não autorizado ou indisponível.');}}
$('homebar').onclick=home;document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('sheetShade').classList.contains('open'))closeSheet();else home();}});
function fit(){const maxWidth=Math.min(innerWidth,406),maxHeight=innerHeight;const scale=Math.min(1,maxWidth/406,maxHeight/860);$('phone').style.transform=`scale(${scale})`;$('stage').style.width=406*scale+'px';$('stage').style.height=860*scale+'px';}
window.addEventListener('resize',fit);setInterval(()=>{$('statusTime').textContent=timeText();if($('largeTime'))$('largeTime').textContent=timeText();if(stopwatchRunning){stopwatchSeconds++;if($('stopwatch'))$('stopwatch').textContent=duration(stopwatchSeconds);}},1000);

home();fit();$('statusTime').textContent=timeText();

document.addEventListener("keydown",e=>{if(e.key==="Escape"){e.preventDefault();back();}});